#include <vector>

using namespace std;

class Solution {
public:
    vector<int> beautifulArray(int n) {
        if (n == 1) return {1};
        vector<int> res, left = beautifulArray((n + 1) / 2), right = beautifulArray(n / 2);
        for (int x : left) res.push_back(2 * x - 1);
        for (int x : right) res.push_back(2 * x);
        return res;
    }
};
